data["character.aemeath.additionalAbilities.1.name"] = "별과 별 사이"
data["character.aemeath.additionalAbilities.1.description"] = "==공명 모드 · 조화 파동==에 있을 경우, 파티 내 캐릭터가 ==「조화 파동 · 이탈」==을 추가하거나 혹은 ==조화 파동 피해==를 입힐 시, 에이메스의 크리티컬 피해가 20% 증가되고, 최대 3스택 중첩이 가능하다. 해당 효과는 캐릭터당 최대 1회만 발생할 수 있다.\n3스택 도달 시, 공명 해방 ==경계를 부순 별빛 · 종결==의 피해가 25% 부스트된다.\n캐릭터가 파티에 편성되거나 모드 전환 시, 해당 효과가 리셋된다.\n\n==공명 모드 · 불꽃==에 있을 경우, 파티 내 캐릭터가 ==「불꽃 효과」==를 추가할 시, 에이메스의 크리티컬 피해가 30% 증가되고, 최대 2스택 중첩이 가능하다. 해당 효과는 캐릭터당 최대 1회만 발생할 수 있다.\n2스택 도달 시, 공명 해방 ==경계를 부순 별빛 · 종결==의 피해가 25% 부스트된다.\n캐릭터가 파티에 편성되거나 모드 전환 시, 해당 효과가 리셋된다"

data["character.aemeath.eidolons.0.name"] = "1. 금빛 가루로 흩뿌려진 첫 새벽"
data["character.aemeath.eidolons.0.description"] = "==즉시 대응== 상태에서 ==강공격 · 에이메스, 강공격 · 메카스카우트==의 크리티컬 피해가 300% 증가되고, 차지 기간 동안 주변의 목표를 끌어당길 수 있다.\n\n에이메스가 다음 조건을 만족한 상태에서 4초를 초과 시, ==즉시 대응 · 찬란한 빛== 상태를 획득한다.\n· 비전투 상태일 경우\n· ==강공격 · 에이메스==, ==강공격 · 메카스카우트==, 공명 해방 ==경계를 부순 별빛 · 종결== 발동 상태가 아닐 경우\n==즉시 대응 · 찬란한 빛==은 ==즉시 대응==의 모든 효과를 이어받고, ==즉시 대응 · 찬란한 빛==은 ==경계를 부순 별빛 · 해방== 상태가 종료되더라도 제거되지 않는다.\n==즉시 대응 · 찬란한 빛==상태에 있고, ==경계를 부순 별빛 · 해방== 상태가 아닐 경우, ==강공격 · 에이메스 · 차지 2단계== 혹은 ==강공격 · 메카스카우트 · 차지 2단계== 발동 시, 100pt의 ==「동기화율」==을 획득할 수 있다.\n\n==공명 모드 · 조화 파동== / ==공명 모드 · 불꽃==에 있을 시, 에이메스가 자신이 발동한 스킬로 직접 피해를 입혀 ==조화 파동 궤적== / ==불꽃의 궤적== 상태가 추가된 목표를 격파 시, ==궤적 봉인 · 조화 파동== / ==궤적 봉인 · 불꽃== 상태를 획득하고, 10초간 지속된다.\n==궤적 봉인 · 조화 파동== / ==궤적 봉인 · 불꽃== 상태에서 격파한 목표에게 추가된 ==조화 파동 궤적== / ==불꽃의 궤적==의 현재 최대 스택을 유지한다.\n에이메스가 다음번 자신이 발동한 스킬로 직접 입힌 피해는 즉시 명중한 목표에게 해당하는 스택의 ==조화 파동 궤적== / ==불꽃의 궤적==을 추가하며, 현재 목표의 ==조화 파동 궤적== / ==불꽃의 궤적== 스택 최대치까지 중첩시킬 수 있다. 동시에 ==궤적 봉인 · 조화 파동== / ==궤적 봉인 · 불꽃== 상태를 제거하고, 1초 이내에 다시 ==궤적 봉인 · 조화 파동== / ==궤적 봉인 · 불꽃==을 획득할 수 없다"

data["character.aemeath.eidolons.1.name"] = "2. 깃털 눈꽃처럼 선율에 실린 마음"
data["character.aemeath.eidolons.1.description"] = "공명 스킬 ==빛나는 날개의 합주 · 강림==의 피해 배율이 100% 상승된다.\n공명 스킬 ==빛나는 날개의 합주 · 등장==의 피해 배율이 100% 상승된다.\n\n==공명 모드 · 조화 파동==에 있을 경우, 공명 스킬 ==빛나는 날개의 합주==가 추가로 입히는 ==조화 파동 피해==로 목표 명중 시, 목표가 받는 공명 스킬 ==빛나는 날개의 합주==가 추가로 입히는 ==조화 파동 피해==의 피해 배율을 20% 상승시키고, 1초간 지속되며, 최대 5스택까지 중첩이 가능하다.\n\n==공명 모드 · 불꽃==에 있을 경우, 다음과 같은 강화 효과를 획득한다.\n· ==별조각의 공진== 상태가 공명 스킬 ==빛나는 날개의 합주==로 폭발시킨 ==「불꽃 효과」==의 피해 배율 상승 효과를 강화시키며, ==「불꽃 효과」==의 메인 목표에게 입히는 피해 배율 상승 효과를 400%로 상승시킨다.\n· ==불꽃의 궤적==이 공명 스킬 ==빛나는 날개의 합주==로 폭발시킨 ==「불꽃 효과」==의 피해 배율 상승 효과를 강화시키고, 스택마다 ==「불꽃 효과」==의 메인 목표에게 입히는 피해 배율 상승 효과를 15%로 상승시킨다.\n· 전투 상태일 경우, 파티 내 등장 캐릭터의 주변 목표가 격파될 시, 즉시 ==「불꽃 효과」== 스택 최대치에 따라 ==「불꽃 효과」==를 폭발시킨다"

data["character.aemeath.eidolons.2.name"] = "3. 침묵 속에 처음처럼 타오르는 불꽃"
data["character.aemeath.eidolons.2.description"] = "공명 해방 ==경계를 부순 별빛 · 종결==의 피해 배율이 100% 상승된다.\n공명 해방 ==경계를 부순 별빛 · 과부하==의 피해 배율이 40% 상승된다.\n\n==즉시 대응== 상태일 경우, ==강공격 · 에이메스, 강공격 · 메카스카우트== 발동 시, 자신이 처해있는 ==공명 모드 · 조화 파동== / ==공명 모드 · 불꽃==에 따라 주변 목표에게 ==「조화 파동 · 이탈」== / ==「불꽃 효과」==를 추가한다.\n\n고유 스킬 ==별과 별 사이==가 다음과 같은 효과로 대체된다.\n\n· ==공명 모드 · 조화 파동==에 있을 경우, 파티 내 캐릭터가 ==「조화 파동 · 이탈」==을 추가하거나 혹은 ==조화 파동 피해==를 입힐 시, 에이메스의 크리티컬 피해가 60% 증가되고, 공명 해방 ==경계를 부순 별빛 · 종결==의 피해가 25% 부스트된다.\n캐릭터가 파티에 편성되거나 모드 전환 시, 해당 효과가 리셋된다.\n\n· ==공명 모드 · 불꽃==에 있을 경우, 파티 내 캐릭터가 ==「불꽃 효과」== 추가 시, 에이메스의 크리티컬 피해가 60% 증가되고, 공명 해방 ==경계를 부순 별빛 · 종결==의 피해가 25% 부스트된다.\n캐릭터가 파티에 편성되거나 모드 전환 시, 해당 효과가 리셋된다"

data["character.aemeath.eidolons.3.name"] = "4. 끝없는 전자 바다에서 추는 춤"
data["character.aemeath.eidolons.3.description"] = "변주 스킬 ==먼하늘에 울려퍼지는 멜로디==, 변주 스킬 ==별빛을 품고 나타난 곳==, 공명 스킬 ==협공 · 돌진==, 공명 스킬 ==빛나는 날개의 합주== 발동 시, 파티 내 캐릭터의 전체 속성 피해 보너스가 20% 증가되고, 30초간 지속된다"

data["character.aemeath.eidolons.4.name"] = "5. 별바다 끝에 닿은 영원의 여정"
data["character.aemeath.eidolons.4.description"] = "에이메스 자신의 스킬로 직접 피해를 입혀 목표를 격파 시, ==「넘쳐 흐르는 찬란한 빛」==은 100%로 리셋된다.\n\n에이메스가 치명적인 피해를 받을 시, 의식을 잃고 ==이차원 전자 유령== 상태에 진입하며, 5초간 지속된다.\n==이차원 전자 유령== 상태에 진입 시, 파티 내 캐릭터에게 에이메스 공격력의 360%에 해당하는 실드를 제공하고, 5초간 지속된다. ==이차원 전자 유령== 상태 종료 시, 에이메스는 의식을 회복하고 HP 최대치의 100%에 해당하는 HP와 30pt의 공명 에너지를 회복한다. 해당 효과는 10분마다 1회 발생할 수 있다.\n에이메스가 의식을 회복할 시, ==이차원 전자 유령== 상태가 종료되고, 해당 효과로 제공된 실드가 제거된다"

data["character.aemeath.eidolons.5.name"] = "6. 봄바람이 그대의 여정을 축복하리"
data["character.aemeath.eidolons.5.description"] = "목표가 받는 에이메스의 공명 해방 피해가 40% 증가된다.\n\n==공명 모드 · 조화 파동==에 있을 시, 에이메스의 조화 파동 피해는 크리티컬을 발생시킬 수 있으며, 크리티컬은 80%, 크리티컬 피해는 275%로 고정된다.\n\n==공명 모드 · 불꽃==에 있는 동시에 전투 상태일 경우, 파티 내 등장 캐릭터의 주변 목표가 받는 불꽃 효과가 발생시킨 피해는 크리티컬을 발생시킬 수 있으며, 크리티컬은 80%, 크리티컬 피해는 275%로 고정된다.\n\n공명 회로 ==적막을 깎아 빚어낸 형태==는 목표에게 추가하는 ==조화 파동 궤적==, ==불꽃의 궤적== 스택이 두 배가 된다.\n\n==공명 모드 · 조화 파동== / ==공명 모드 · 불꽃==에 있는 동시에 전투 상태일 경우, 파티 내 등장 캐릭터의 주변 목표의 ==조화 파동 궤적== / ==불꽃의 궤적==의 스택 최대치가 60스택으로 증가된다. 에이메스가 공명 스킬 ==빛나는 날개의 합주==를 발동하는 기간 동안, 주변 목표에게 10스택의 ==조화 파동 궤적== / ==불꽃의 궤적==을 추가하고, 30초간 지속된다."

data["character.aemeath.concertDissipation.description"] = "목표의 ==「부조화 수치」==가 가득 찰 시, 에이메스는 해당 목표에게 ==「조화도 파괴」==를 발동할 수 있다.\n==「조화도 파괴」== 발동 후, 일정 시간 내에 ==일반 공격==을 짧게 누르면, ==일반 공격 3단==을 발동한다.\n\n==「조화 파동 · 간섭」== 대응: 파티 내 캐릭터가 목표에게 ==「조화도 파괴」== 피해를 입히고, 목표가 ==「조화 파동 · 간섭」== 상태에 진입 시, 에이메스는 ==조화 파동 대응 · 초신성== 효과를 발생시킨다. 해당 피해는 동일한 목표에게 8초마다 최대 1회만 적용된다"

data["character.aemeath.terms.0.name"] = "불꽃의 궤적"
data["character.aemeath.terms.0.description"] = "==공명 모드 · 불꽃==에 있을 시, ==공명 스킬 빛나는 날개의 합주== 기간 동안, 목표가 ==불꽃의 궤적==을 보유할 경우, 목표의 ==불꽃의 궤적==을 제거하고, ==「불꽃 효과」== 스택 최대치에 따라 ==「불꽃 효과」== 를 폭발시키고, 이번 폭발은 ==「불꽃 효과」== 스택을 제거하지 않는다. 목표의 제거된 ==불꽃의 궤적== 스택에 따라 이번 ==「불꽃 효과」== 가 ==「불꽃 효과」== 의 메인 목표에게 입히는 피해 배율을 상승시키며, 각 스택마다 10% 상승시킨다"

